const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Sakha Republic (Yakutia) approximate bounds
  const sakha = ee.Geometry.Polygon([
    [[105, 55], [165, 55], [165, 73], [105, 73], [105, 55]]
  ]);

  const startDate = '2020-08-06';
  const endDate = '2020-08-07';

  // 2. Data Acquisition - Try FIRMS MODIS first
  let fireCol = ee.ImageCollection('FIRMS')
    .filterDate(startDate, endDate)
    .filterBounds(sakha);

  let colSize = fireCol.size().getInfo();
  console.log(`FIRMS collection size: ${colSize}`);

  // If FIRMS not available, try MODIS Thermal Anomalies
  if (colSize === 0) {
    fireCol = ee.ImageCollection('MODIS/006/MOD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(sakha);

    colSize = fireCol.size().getInfo();
    console.log(`MODIS MOD14A1 collection size: ${colSize}`);
  }

  // If still no data, try VIIRS
  if (colSize === 0) {
    fireCol = ee.ImageCollection('MODIS/006/VNP14A1')
      .filterDate(startDate, endDate)
      .filterBounds(sakha);

    colSize = fireCol.size().getInfo();
    console.log(`VIIRS VNP14A1 collection size: ${colSize}`);
  }

  if (colSize === 0) {
    console.log('No fire data available for August 6, 2020 in Sakha Republic.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Use MOD14A1 (daily fire product)
  const fireImage = fireCol.first();
  const fireMask = fireImage.select('FireMask');

  // FireMask: values 7-9 indicate fire pixels
  // 7 = low confidence, 8 = nominal confidence, 9 = high confidence
  const firePixels = fireMask.gte(7).and(fireMask.lte(9));

  // 4. Count fire pixels
  const fireStats = firePixels.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 1000,
    maxPixels: 1e9
  });

  const fireCount = fireStats.get('FireMask').getInfo();

  if (fireCount === null || fireCount === undefined) {
    console.log('Fire count calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Active fire pixels detected: ${fireCount}`);

  // 5. Validation & Final Answer
  if (fireCount === 0) {
    console.log('No valid fire pixels found.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (fireCount > 8) {
    console.log(`Yes, ${fireCount} fires detected (> 8).`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No, only ${fireCount} fires detected (<= 8).`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
